#include <iostream>#include <vector>#include <cmath>  // for abs()using namespace std; int main() {    vector<vector<int>> input(5, vector<int>(5));  // 5x5 matrix     int oneI = 0, oneJ = 0;     // Input    for (int i = 0; i < 5; i++) {        for (int j = 0; j < 5; j++) {            cin >> input[i][j];            if (input[i][j] == 1) {                oneI = i;                oneJ = j;            }        }    }     // Calculate Manhattan distance from center (2,2)    int ans = abs(2 - oneI) + abs(2 - oneJ);    cout << ans << endl;     return 0;}